<script setup>
import {computed,ref} from 'vue';
import {api} from '../services/accounting.js';
import {farmSaleError} from '../services/farms.js';
import {calculateFarmSale} from '../../../shared/farm-sale-money.js';
import FormDialog from './FormDialog.vue';
const props=defineProps({lot:Object,sale:Object}),emit=defineEmits(['close','saved']);
const form=ref(props.sale?{...props.sale}:{lot_id:props.lot.id,sale_date:new Date().toLocaleDateString('sv-SE'),pigs:'',kg_per_pig:'',price_per_kg:'',notes:'',request_id:crypto.randomUUID()});
const busy=ref(false),error=ref(''),confirmDelete=ref(false);
const calculated=computed(()=>{try{return calculateFarmSale(form.value);}catch{return null;}});
const number=(value,digits)=>Number(value).toLocaleString('es-ES',{maximumFractionDigits:digits});
const money=value=>Number(value).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
async function save(){if(busy.value||confirmDelete.value)return;busy.value=true;error.value='';try{calculateFarmSale(form.value);const value=form.value,result=await api('/farms/sales'+(value.id?'/'+value.id:''),{method:value.id?'PATCH':'POST',body:value});emit('saved',result);}catch(cause){error.value=farmSaleError(cause);}finally{busy.value=false;}}
async function remove(){if(busy.value||!confirmDelete.value)return;busy.value=true;error.value='';try{await api('/farms/sales/'+form.value.id,{method:'DELETE',body:{version:form.value.version}});emit('saved',{removed:true});}catch(cause){error.value=farmSaleError(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog :title="sale?'Editar venta manual':'Nueva venta manual'" :busy="busy" @close="emit('close')"><p><strong>Lote {{ lot.code }}</strong></p><form class="sale-form" @submit.prevent="save"><fieldset :disabled="busy||confirmDelete"><div class="sale-fields"><label for="sale-date">Fecha de venta<input id="sale-date" v-model="form.sale_date" type="date" required></label><label for="sale-pigs">Número de cerdos<input id="sale-pigs" v-model="form.pigs" type="number" min="1" max="10000000" step="1" required></label><label for="sale-weight">Kilos por cerdo<input id="sale-weight" v-model="form.kg_per_pig" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,3})?" maxlength="8" placeholder="Ej. 115,5" required></label><label for="sale-price">Precio por kilo (sin IVA)<input id="sale-price" v-model="form.price_per_kg" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,5})?" maxlength="12" placeholder="Ej. 1,65" required></label></div><label for="sale-notes">Notas (opcional)<textarea id="sale-notes" v-model="form.notes" rows="2" maxlength="2000"></textarea></label></fieldset><div class="sale-calculated" aria-live="polite"><div><small>Kilos totales</small><strong>{{ calculated?number(calculated.total_kg,3)+' kg':'—' }}</strong></div><div><small>Importe sin IVA</small><strong>{{ calculated?money(calculated.total_amount):'—' }}</strong></div></div><p class="muted">Cerdos × kilos por cerdo × precio por kilo.</p><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><div v-if="confirmDelete" class="sale-delete"><p>¿Eliminar esta venta de {{ money(sale.total_amount) }}? Se actualizarán los ingresos y el resultado del lote.</p><div class="actions"><button type="button" class="button clear-danger" :disabled="busy" @click="remove">Eliminar venta</button><button type="button" class="button" :disabled="busy" @click="confirmDelete=false">Conservar venta</button></div></div><div v-else class="actions"><button class="button primary" :disabled="busy||!calculated">{{ busy?'Guardando…':'Guardar venta' }}</button><button v-if="sale" type="button" class="button clear-danger" :disabled="busy" @click="confirmDelete=true">Eliminar venta</button><button type="button" class="button" :disabled="busy" @click="emit('close')">Cancelar</button></div></form></FormDialog></template>
<style scoped>.sale-form{display:grid;gap:18px;margin-top:20px}.sale-form fieldset{border:0;padding:0;margin:0;min-width:0;display:grid;gap:16px}.sale-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.sale-calculated{display:flex;gap:30px;justify-content:space-between;padding:18px;border:1px solid var(--primary-border);background:var(--primary-soft);border-radius:8px}.sale-calculated>div{display:grid;gap:6px}.sale-calculated small{color:#65748a}.sale-calculated strong{font-size:20px}.sale-delete{display:grid;gap:18px}@media(max-width:550px){.sale-fields{grid-template-columns:1fr}.sale-calculated{flex-wrap:wrap}}</style>
